from pathlib import Path
import re

ROOT=Path('unified-scanner/app/src/main/java/com/suhas/nseunifiedscanner')
TEST=Path('unified-scanner/app/src/test/java/com/suhas/nseunifiedscanner')
mp=ROOT/'MainActivity.java'
gp=Path('unified-scanner/app/build.gradle')

def must(path, old, new):
    p=Path(path); s=p.read_text()
    if old not in s: raise SystemExit(f'v1.6.5 anchor missing in {p}: {old[:180]!r}')
    p.write_text(s.replace(old,new,1))

# Networking imports used only by the explicit Detect Current Public IP button.
must(mp,
'''import java.text.SimpleDateFormat;\nimport java.util.Date;\nimport java.util.Locale;\n''',
'''import java.io.BufferedReader;\nimport java.io.InputStreamReader;\nimport java.net.HttpURLConnection;\nimport java.net.URL;\nimport java.text.SimpleDateFormat;\nimport java.util.Date;\nimport java.util.Locale;\n''')

# Make credentials easy to discover directly below Connection Health.
must(mp,
'''        LinearLayout conn=card();conn.addView(txt("CONNECTION HEALTH",12,ACCENT,true));connectivity=txt("Groww API  ○ CHECKING\\nStatic IP  ○ CHECKING\\nNSE feed  ○ CHECKING",12,TEXT,true);conn.addView(connectivity);body.addView(conn);\n        body.addView(space(10));\n''',
'''        LinearLayout conn=card();conn.addView(txt("CONNECTION HEALTH",12,ACCENT,true));connectivity=txt("Groww API  ○ CHECKING\\nStatic IP  ○ CHECKING\\nNSE feed  ○ CHECKING",12,TEXT,true);conn.addView(connectivity);conn.addView(space(9));Button growwSettings=button("GROWW CREDENTIALS / STATIC IP",CARD2,TEXT);growwSettings.setOnClickListener(v->settingsDialog());conn.addView(growwSettings,new LinearLayout.LayoutParams(-1,dp(46)));body.addView(conn);\n        body.addView(space(10));\n''')

old='''    private void settingsDialog(){\n        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(8),dp(20),0);EditText api=field("Groww API key",SecureStore.get(this,SecureStore.API_KEY),false);EditText secret=field("Groww TOTP secret",SecureStore.get(this,SecureStore.TOTP_SECRET),true);EditText ip=field("Groww-whitelisted Dedicated IP",SecureStore.get(this,SecureStore.DEDICATED_IP),false);TextView info=txt("Credentials are encrypted with Android Keystore. TEST MODE is fixed at ₹10,000 trade value per BUY-qualified prediction, regardless of wallet balance. BUY requires the configured public IP to match exactly. Connection Health turns green only after actual API/feed/IP checks.",11,MUTED,false);box.addView(info);\n        AlertDialog d=new AlertDialog.Builder(this).setTitle("Secure Groww settings").setView(box).setNegativeButton("Cancel",null).setNeutralButton("AUTHENTICATE",null).setPositiveButton("SAVE",null).create();d.setOnShowListener(x->{d.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{SecureStore.put(this,SecureStore.API_KEY,api.getText().toString().trim());SecureStore.put(this,SecureStore.TOTP_SECRET,secret.getText().toString().trim());SecureStore.put(this,SecureStore.DEDICATED_IP,ip.getText().toString().trim());prefs().edit().putInt("static_ip_state",0).apply();Toast.makeText(this,"Settings saved",Toast.LENGTH_SHORT).show();d.dismiss();}catch(Exception e){Toast.makeText(this,"Save failed: "+e.getMessage(),Toast.LENGTH_LONG).show();}});d.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->{try{SecureStore.put(this,SecureStore.API_KEY,api.getText().toString().trim());SecureStore.put(this,SecureStore.TOTP_SECRET,secret.getText().toString().trim());SecureStore.put(this,SecureStore.DEDICATED_IP,ip.getText().toString().trim());prefs().edit().putInt("static_ip_state",0).apply();send(UnifiedService.ACTION_AUTH,null);Toast.makeText(this,"Authentication requested",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Could not save credentials",Toast.LENGTH_LONG).show();}});});d.show();}\n'''
new='''    private void settingsDialog(){\n        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(8),dp(20),0);\n        box.addView(txt("GROWW API KEY",10,MUTED,true));\n        EditText api=field("Enter Groww API key",SecureStore.get(this,SecureStore.API_KEY),false);box.addView(api);\n        box.addView(txt("GROWW TOTP / API SECRET",10,MUTED,true));\n        EditText secret=field("Enter Groww TOTP / API secret",SecureStore.get(this,SecureStore.TOTP_SECRET),true);box.addView(secret);\n        box.addView(txt("GROWW-WHITELISTED STATIC PUBLIC IP",10,MUTED,true));\n        EditText ip=field("Enter or auto-detect public IP",SecureStore.get(this,SecureStore.DEDICATED_IP),false);box.addView(ip);\n        Button detect=button("AUTO-DETECT CURRENT PUBLIC IP",CARD2,TEXT);box.addView(detect,new LinearLayout.LayoutParams(-1,dp(46)));\n        box.addView(space(8));TextView info=txt("The detect button reads this phone's current public internet IP and fills the field. Confirm that this is the same IP whitelisted in Groww before enabling LIVE. Credentials are encrypted with Android Keystore. Test order size remains capped near ₹10,000.",11,MUTED,false);box.addView(info);\n        AlertDialog d=new AlertDialog.Builder(this).setTitle("Groww connection settings").setView(box).setNegativeButton("CANCEL",null).setNeutralButton("SAVE + CONNECT",null).setPositiveButton("SAVE",null).create();\n        detect.setOnClickListener(v->detectPublicIp(ip,detect));\n        d.setOnShowListener(x->{d.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);\n            d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(saveGrowwSettings(api,secret,ip)){Toast.makeText(this,"Groww settings saved",Toast.LENGTH_SHORT).show();d.dismiss();}});\n            d.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->{if(saveGrowwSettings(api,secret,ip)){send(UnifiedService.ACTION_AUTH,null);Toast.makeText(this,"Saved • Groww authentication requested",Toast.LENGTH_SHORT).show();}});\n        });d.show();\n    }\n\n    private boolean saveGrowwSettings(EditText api,EditText secret,EditText ip){\n        String a=api.getText().toString().trim(),s=secret.getText().toString().trim(),p=ip.getText().toString().trim();\n        if(a.isEmpty()||s.isEmpty()){Toast.makeText(this,"Enter both Groww API key and TOTP / API secret",Toast.LENGTH_LONG).show();return false;}\n        if(p.isEmpty()){Toast.makeText(this,"Enter or auto-detect the Groww-whitelisted public IP",Toast.LENGTH_LONG).show();return false;}\n        try{SecureStore.put(this,SecureStore.API_KEY,a);SecureStore.put(this,SecureStore.TOTP_SECRET,s);SecureStore.put(this,SecureStore.DEDICATED_IP,p);SecureStore.remove(this,SecureStore.ACCESS_TOKEN);SecureStore.remove(this,SecureStore.ACCESS_DAY);prefs().edit().putInt("static_ip_state",0).putBoolean("groww_api_ok",false).apply();return true;}\n        catch(Exception e){Toast.makeText(this,"Secure save failed: "+e.getMessage(),Toast.LENGTH_LONG).show();return false;}\n    }\n\n    private void detectPublicIp(EditText ip,Button detect){\n        detect.setEnabled(false);detect.setText("DETECTING…");\n        new Thread(()->{String found="";HttpURLConnection c=null;try{c=(HttpURLConnection)new URL("https://api.ipify.org").openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setRequestProperty("User-Agent","NSEUnifiedScanner/1.6.5 Android");try(BufferedReader br=new BufferedReader(new InputStreamReader(c.getInputStream()))){String line=br.readLine();found=line==null?"":line.trim();}}catch(Exception ignore){}finally{if(c!=null)c.disconnect();}\n            final String value=found;runOnUiThread(()->{detect.setEnabled(true);detect.setText("AUTO-DETECT CURRENT PUBLIC IP");if(value.isEmpty())Toast.makeText(this,"Could not detect public IP • check internet connection",Toast.LENGTH_LONG).show();else{ip.setText(value);ip.setSelection(value.length());Toast.makeText(this,"Current public IP detected • verify it is Groww-whitelisted",Toast.LENGTH_LONG).show();}});\n        },"scanner-ip-detect").start();\n    }\n'''
must(mp,old,new)

# Update footer/help labels.
p=mp;s=p.read_text().replace('v1.6.4 • pattern memory + 2-stage confirmation','v1.6.5 • restored Groww credential UI + public-IP detect • pattern memory + 2-stage confirmation').replace('v1.6.4 requires 2-stage 1-minute persistence','v1.6.5 requires 2-stage 1-minute persistence');p.write_text(s)

# Version bump.
s=gp.read_text();s=re.sub(r'versionCode\s+\d+', 'versionCode 165', s, count=1);s=re.sub(r"versionName\s+'[^']+'", "versionName '1.6.5'", s, count=1);gp.write_text(s)

